(function(root){function synthetic(kind){let seed=42,x=100,d=new Date('2023-01-02T00:00:00Z'),rows=[];function rand(){seed=(1664525*seed+1013904223)>>>0;return(seed+.5)/4294967296}for(let i=0;i<756;i++){while([0,6].includes(d.getUTCDay()))d.setUTCDate(d.getUTCDate()+1);let z=Math.sqrt(-2*Math.log(rand()))*Math.cos(2*Math.PI*rand());x*=Math.exp((kind==='trend'?(i<260?.0012:i<480?-.0006:.001):.03*Math.log(100/x))+.012*z);rows.push({date:d.toISOString().slice(0,10),close:x});d.setUTCDate(d.getUTCDate()+1)}return rows}
function backtest(rows,{fast,slow,cost,strategy}){if(!(Number.isInteger(fast)&&Number.isInteger(slow)&&fast>=2&&slow>fast&&slow<=250&&rows.length>slow&&cost>=0&&cost<=200))throw Error('Use integer windows with fast < slow (maximum 250).');let equity=100,benchmark=100,peak=100,pos=0,turns=0;let out=[{...rows[slow-1],position:0,equity,benchmark,drawdown:0,ret:0}];for(let i=slow;i<rows.length;i++){let prev=rows[i-1].close;const avg=n=>rows.slice(i-n,i).reduce((s,r)=>s+r.close,0)/n;let target=+(strategy==='trend'?avg(fast)>avg(slow):prev<avg(fast)),change=Math.abs(target-pos),ret=target*(rows[i].close/prev-1)-change*cost/10000;equity*=1+ret;benchmark*=rows[i].close/prev-(i===slow?cost/10000:0);peak=Math.max(peak,equity);turns+=change;pos=target;out.push({...rows[i],position:pos,equity,benchmark,drawdown:equity/peak-1,ret})}let r=out.slice(1).map(x=>x.ret),n=r.length,mean=r.reduce((a,b)=>a+b,0)/n,sd=Math.sqrt(r.reduce((s,x)=>s+(x-mean)**2,0)/(n-1));return{out,total:equity/100-1,cagr:(equity/100)**(252/n)-1,sharpe:sd?mean/sd*Math.sqrt(252):0,dd:Math.min(...out.map(x=>x.drawdown)),turns}}
function parseCSV(text){let lines=text.trim().replace(/^\uFEFF/,'').split(/\r?\n/),heads=lines.shift().split(',').map(x=>x.trim().toLowerCase()),di=heads.indexOf('date'),ci=heads.indexOf('close');if(di<0||ci<0)throw Error('CSV requires date,close headers.');let rows=lines.map((line,i)=>{let p=line.split(','),date=(p[di]||'').trim(),close=Number(p[ci]);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date||!Number.isFinite(close)||close<=0)throw Error('Invalid date or price at row '+(i+2));return{date,close}});if(rows.length<260||rows.length>20000)throw Error('Use 260–20,000 daily observations.');for(let i=1;i<rows.length;i++)if(rows[i].date<=rows[i-1].date)throw Error('Dates must be unique and ascending.');return rows}root.AsnyaEngine={synthetic,backtest,parseCSV};if(typeof module!=='undefined')module.exports=root.AsnyaEngine})(globalThis);

(function(root){
 const MAX=1e12;
 function number(x,min,max,name){if(typeof x!=='number'||!Number.isFinite(x)||x<min||x>max)throw Error('Invalid '+name);return x}
 function validatePortfolio(input){
  if(!input||input.version!==1||input.currency!=='USD'||!Array.isArray(input.holdings)||input.holdings.length>100)throw Error('Expected version 1 USD portfolio with at most 100 holdings');
  const cash=number(input.cash,0,MAX,'cash'),seen=new Set();
  const holdings=input.holdings.map(h=>{
   if(!h||typeof h.symbol!=='string'||!(/^[A-Z0-9.^_-]{1,16}$/).test(h.symbol)||seen.has(h.symbol))throw Error('Symbols must be unique uppercase identifiers');seen.add(h.symbol);
   return {symbol:h.symbol,quantity:number(h.quantity,0.000001,MAX,'quantity'),cost:number(h.cost,0.000001,MAX,'unit cost'),price:number(h.price,0.000001,MAX,'unit price')};
  });return {version:1,currency:'USD',cash,holdings};
 }
 function portfolioSummary(input){const book=validatePortfolio(input);const holdings=book.holdings.map(h=>({...h,value:h.quantity*h.price,basis:h.quantity*h.cost}));const invested=holdings.reduce((s,h)=>s+h.value,0),basis=holdings.reduce((s,h)=>s+h.basis,0),total=invested+book.cash,pnl=invested-basis;
 return {cash:book.cash,invested,basis,total,pnl,pnlPercent:basis?pnl/basis:null,largestWeight:total?Math.max(0,...holdings.map(h=>h.value/total)):0,holdings:holdings.map(h=>({...h,pnl:h.value-h.basis,weight:total?h.value/total:0}))};
 }
 function stressPortfolio(input,percent,target='all'){number(percent,-100,1000,'shock');const before=portfolioSummary(input);if(target!=='all'&&!before.holdings.some(h=>h.symbol===target))throw Error('Unknown shock target');let delta=before.holdings.reduce((sum,h)=>sum+((target==='all'||target===h.symbol)?h.value*percent/100:0),0);return {before:before.total,after:before.total+delta,delta,change:before.total?delta/before.total:null,percent,target};}
 Object.assign(root.AsnyaEngine,{validatePortfolio,portfolioSummary,stressPortfolio});
})(globalThis);
